#![allow(dead_code)]
#[path="../handheld/src/margin.rs"]mod margin;
#[path="../handheld/src/timing.rs"]mod timing;
#[path="../handheld/src/timing_line.rs"]mod timing_line;
use margin::{Bus,Outcome};use timing::*;use timing_line::{Parser,Event};
struct Fake {shadow:Timing,pair:Timing,preset:u8,pending:bool,valid:bool,ready:bool,online:bool,result:u8,seq:u8,core:u32,build:u32,magic:u32,schema:u32,writes:Vec<(u32,u32)>,ops:usize,fail:usize,reject:u8,race:bool}
impl Default for Fake{fn default()->Self{Self{shadow:Timing::current(),pair:Timing::current(),preset:0,pending:false,valid:true,ready:true,online:true,result:2,seq:7,core:0x4d425631,build:margin::BUILD,magic:MAGIC,schema:SCHEMA,writes:vec![],ops:0,fail:0,reject:0,race:false}}}
impl Fake{fn status(&self)->u32{self.preset as u32|((self.pending as u32)<<7)|((self.valid as u32)<<8)|((self.online as u32)<<9)|((self.ready as u32)<<10)|((self.result as u32)<<16)|((self.seq as u32)<<24)}fn apply(&mut self){self.pair=self.shadow;self.pending=false;self.ready=true;self.valid=true;self.seq=self.seq.wrapping_add(1);self.result=2;}}
impl Bus for Fake{fn read(&mut self,off:u32)->Result<u32,()>{self.ops+=1;if self.ops==self.fail{return Err(())}let val=match off{0=>self.core,4=>0x10000,0x184=>self.build,0x090=>self.magic,0x09c=>self.schema,0x094=>self.shadow.horizontal,0x098=>self.shadow.vertical,0x0a0=>self.pair.horizontal,0x0a4=>self.pair.vertical,0x0a8=>self.status(),_=>panic!("read{off:x}")};if self.race&&off==0xa0{self.race=false;self.pair=Timing::official();self.seq+=1;}Ok(val)}fn write(&mut self,off:u32,v:u32)->Result<(),()>{self.ops+=1;self.writes.push((off,v));if self.reject!=0{self.result=self.reject}else{match off{0x094=>{self.shadow.horizontal=v;self.result=6},0x098=>{self.shadow.vertical=v;self.result=6},0x09c=>{self.shadow=match v{0=>Timing::current(),1=>Timing::official(),2=>self.shadow,_=>panic!()};self.preset=v as u8;self.pending=true;self.ready=false;self.result=1},_=>panic!("write{off:x}")}}if self.ops==self.fail{Err(())}else{Ok(())}}}
fn controller(choice:Choice)->Controller{let mut c=Controller::new();c.request(b'T',choice).unwrap();c}
fn finish(c:&mut Controller,b:&mut Fake)->Report{for _ in 0..34{let n=b.ops;let report=c.step(b);assert!(b.ops-n<=9);if let Some(report)=report{return report}if b.pending{b.apply()}}panic!("not bounded")}
#[test]fn canonical_back_before_front_roundtrip_and_presets(){let official=Timing::official();assert_eq!(official.horizontal,4|(119<<10)|(2<<20));assert_eq!(official.vertical,4|(2<<10)|(3<<20));assert_eq!(Timing::decode(official.horizontal,official.vertical),Ok(official));let current=Timing::current();assert_eq!(current.horizontal,4|(10<<10)|(47<<20));assert_eq!(current.vertical,4|(20<<10)|(10<<20));}
#[test]fn geometry_validation_uses_wide_sums_before_any_bus(){for v in [[0,10,47,4,20,10],[4,10,1,4,20,10],[4,10,47,0,20,10],[4,10,47,1,0,0],[4,10,47,1,0,1],[600,0,2,4,20,10],[4,10,47,300,0,1],[65535,65535,65535,4,20,10]]{assert!(Timing::new(v).is_err(),"{v:?}");}assert!(Timing::new([1,0,2,1,1,1]).is_ok());let mut c=Controller::new();assert_eq!(c.request(b'T',Choice::Custom(Timing{horizontal:0,vertical:0})).unwrap_err().outcome,Outcome::Range);assert!(!c.active());}
#[test]fn custom_stages_both_and_reads_back_before_single_atomic_apply(){let mut c=controller(Choice::Custom(Timing::official()));let mut b=Fake::default();let r=finish(&mut c,&mut b);assert_eq!(r.outcome,Outcome::Applied);assert_eq!(r.applied,Some(Timing::official()));assert_eq!(b.writes,[(0x94,Timing::official().horizontal),(0x98,Timing::official().vertical),(0x9c,2)]);}
#[test]fn presets_only_write_atomic_command(){for(choice,value)in[(Choice::Official,1),(Choice::Current,0)]{let mut c=controller(choice);let mut b=Fake::default();assert_eq!(finish(&mut c,&mut b).outcome,Outcome::Applied);assert_eq!(b.writes,[(0x9c,value)]);}}
#[test]fn query_never_writes_and_invalid_startup_has_no_applied_pair(){let mut c=controller(Choice::Query);let mut b=Fake::default();let r=finish(&mut c,&mut b);assert_eq!(r.outcome,Outcome::Status);assert_eq!(r.applied,Some(Timing::current()));assert!(b.writes.is_empty());let mut c=controller(Choice::Query);let mut b=Fake{valid:false,pending:true,..Default::default()};let r=c.step(&mut b).unwrap();assert_eq!(r.outcome,Outcome::Status);assert!(r.applied.is_none());assert!(!r.apply_attempted);}
#[test]fn wrong_build_magic_schema_core_never_get_writes(){for field in 0..4{let mut c=controller(Choice::Official);let mut b=Fake::default();match field{0=>b.core=0,1=>b.build-=1,2=>b.magic=0,_=>b.schema+=1};assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Identity);assert!(b.writes.is_empty());}}
#[test]fn every_custom_io_site_terminates_without_retry_or_rollback(){for fail in 1..=48{let mut c=controller(Choice::Custom(Timing::official()));let mut b=Fake{fail,..Default::default()};let r=finish(&mut c,&mut b);assert_eq!(r.outcome,Outcome::Io,"op{fail}");assert!(r.applied.is_none());assert!(r.status.is_none());let n=b.ops;assert!(c.step(&mut b).is_none());assert_eq!(n,b.ops);assert!(b.writes.iter().filter(|&&(off,_)|off==0x9c).count()<=1);}}
#[test]fn partial_shadow_failure_cannot_apply_or_alter_display(){let mut c=controller(Choice::Custom(Timing::official()));let mut b=Fake{fail:20,..Default::default()};let r=finish(&mut c,&mut b);assert_eq!(r.outcome,Outcome::Io);assert!(!r.apply_attempted);assert_eq!(b.pair,Timing::current());assert!(b.writes.iter().all(|&(off,_)|off!=0x9c));}
#[test]fn changed_shadow_is_detected_in_apply_lock_before_commit(){let mut c=controller(Choice::Custom(Timing::official()));let mut b=Fake::default();for _ in 0..3{assert!(c.step(&mut b).is_none());}b.shadow.horizontal=Timing::current().horizontal;assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Mismatch);assert!(b.writes.iter().all(|&(off,_)|off!=0x9c));}
#[test]fn coherent_query_retries_pair_after_sequence_race(){let mut c=controller(Choice::Query);let mut b=Fake{race:true,..Default::default()};let r=finish(&mut c,&mut b);assert_eq!(r.outcome,Outcome::Status);assert_eq!(r.applied,Some(Timing::official()));assert!(b.writes.is_empty());}
#[test]fn application_requires_pending_clear_valid_and_new_sequence(){let mut c=controller(Choice::Official);let mut b=Fake::default();assert!(c.step(&mut b).is_none());assert!(c.step(&mut b).is_none());b.apply();b.seq=7;assert!(c.step(&mut b).is_none());b.seq=8;assert_eq!(finish(&mut c,&mut b).outcome,Outcome::Applied);}
#[test]fn sequence_wrap_receipt_is_valid(){let mut c=controller(Choice::Official);let mut b=Fake{seq:255,..Default::default()};assert_eq!(finish(&mut c,&mut b).outcome,Outcome::Applied);}
#[test]fn foreign_rejection_during_pending_does_not_overrule_matching_receipt(){let mut c=controller(Choice::Official);let mut b=Fake::default();c.step(&mut b);b.result=4;assert!(c.step(&mut b).is_none());b.apply();b.result=4;assert_eq!(finish(&mut c,&mut b).outcome,Outcome::Applied);}
#[test]fn rejected_commands_and_link_reset_report_without_retry(){for(code,outcome)in[(3,Outcome::Range),(4,Outcome::Busy),(5,Outcome::LinkReset)]{let mut c=controller(Choice::Official);let mut b=Fake{reject:code,..Default::default()};c.step(&mut b);assert_eq!(c.step(&mut b).unwrap().outcome,outcome);assert_eq!(b.writes.len(),1);}}
#[test]fn never_acknowledged_apply_and_explicit_deadline_are_bounded(){let mut c=controller(Choice::Official);let mut b=Fake::default();c.step(&mut b);let r=loop{if let Some(r)=c.step(&mut b){break r}};assert_eq!(r.outcome,Outcome::Timeout);assert!(r.applied.is_none());assert_eq!(b.writes.len(),1);let mut c=controller(Choice::Official);assert_eq!(c.expire().unwrap().outcome,Outcome::Timeout);}
#[test]fn busy_before_stage_and_between_stages_never_queues_an_apply(){let mut c=controller(Choice::Custom(Timing::official()));let mut b=Fake{pending:true,..Default::default()};assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Busy);assert!(b.writes.is_empty());let mut c=controller(Choice::Custom(Timing::official()));let mut b=Fake::default();c.step(&mut b);c.step(&mut b);b.pending=true;assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Busy);assert_eq!(b.writes.len(),1);}
fn line(bytes:&[u8])->Result<[u16;6],timing_line::Error>{let mut p=Parser::new();for(i,&byte)in bytes.iter().enumerate(){if let Event::Complete(r)=p.feed(byte,(i*20)as u64){return r}}panic!("no complete line")}
#[test]fn canonical_ascii_line_and_crlf_preserve_field_order(){assert_eq!(line(b"T4,119,2,4,2,3\n"),Ok([4,119,2,4,2,3]));assert_eq!(line(b"T4,10,47,4,20,10\r\n"),Ok([4,10,47,4,20,10]));}
#[test]fn malformed_custom_lines_never_fall_back_to_legacy_commands(){for bytes in [b"T4,6,8,c,x,h\n".as_slice(),b"T4,,2,4,2,3\n",b"T4,119,2,4,2,3,8\n",b"T+4,119,2,4,2,3\n",b"T4, 119,2,4,2,3\n",b"T65536,1,2,4,2,3\n"]{let mut p=Parser::new();let mut failed=false;for &byte in bytes{match p.feed(byte,1){Event::Pass=>panic!("legacy dispatch escaped"),Event::Complete(r)=>{assert!(r.is_err());failed=true},_=>{}}}assert!(failed);}}
#[test]fn timeout_and_overflow_drain_through_lf_not_into_queue_keys(){for overflow in [false,true]{let mut p=Parser::new();p.feed(b'T',0);if overflow{for _ in 0..49{p.feed(b'4',1);}}else{assert_eq!(p.timeout(1500),Some(timing_line::Error::Timeout));assert_eq!(p.timeout(1600),None);}for &byte in b"468cxfghT"{assert!(matches!(p.feed(byte,1700),Event::Consumed));}assert!(matches!(p.feed(b'\n',1800),Event::Consumed));assert!(matches!(p.feed(b'8',1801),Event::Pass));}}
#[test]fn late_lf_enforces_deadline_even_without_tick(){let mut p=Parser::new();p.feed(b'T',0);assert!(matches!(p.feed(b'\n',1500),Event::Complete(Err(timing_line::Error::Timeout))));assert!(matches!(p.feed(b'8',1501),Event::Pass));}
#[test]fn fixed_parser_and_controller_storage_has_no_frame_or_heap_buffer(){println!("HOST_TIMING_CONTROLLER_BYTES={} HOST_PARSER_BYTES={}",std::mem::size_of::<Controller>(),std::mem::size_of::<Parser>());assert!(std::mem::size_of::<Controller>()<=96);assert!(std::mem::size_of::<Parser>()<=80);}

#[test]fn matching_timing_receipt_offline_or_notready_is_not_applied(){for offline in [true,false]{let mut c=controller(Choice::Official);let mut b=Fake::default();c.step(&mut b);b.apply();if offline{b.online=false}else{b.ready=false}assert!(c.step(&mut b).is_none());b.online=true;b.ready=true;assert_eq!(finish(&mut c,&mut b).outcome,Outcome::Applied);}}
